function cashPermissionV164(user=state.user){
  if(!user)return'nenhum';
  if(user.caixaPermissao)return user.caixaPermissao;
  if(['admin','gestao'].includes(user.perfil))return'gestor';
  if(['secretaria','cantina'].includes(user.perfil))return'operador';
  return'nenhum';
}
function isCashManagerV164(user=state.user){return cashPermissionV164(user)==='gestor'}
